class QCInstance:
    def __init__(
        self,
        test_instance_name="",
        test_lab_path="",
        test_set_name="",
        test_instance_id=None,
        qc_domain="",
        qc_project="",
    ):
        self._test_instance_name = test_instance_name
        self._test_lab_path = test_lab_path
        self._test_set_name = test_set_name
        self._test_instance_id = test_instance_id
        self._qc_domain = qc_domain
        self._qc_project = qc_project

    @property
    def test_lab_path(self):
        """Path to QC test lab."""
        return self._test_lab_path

    @property
    def test_set_name(self):
        """Name of QC test set."""
        return self._test_set_name

    @property
    def test_instance_name(self):
        """Name of QC test instance."""
        return self._test_instance_name

    @property
    def test_instance_id(self):
        """ID of QC test instance."""
        return self._test_instance_id

    @test_instance_id.setter
    def test_instance_id(self, qc_id):
        """ID of QC test instance."""
        if qc_id:
            self._test_instance_id = qc_id

    @property
    def qc_domain(self):
        """ID of QC test instance."""
        return self._qc_domain

    @property
    def qc_project(self):
        """ID of QC test instance."""
        return self._qc_project

    def status(self):
        """Return if QCInstance has any properties set"""
        if self.test_instance_id or (
            self.test_lab_path and self.test_set_name and self.test_instance_name
        ):
            return "[With QC]"
        else:
            return "[ No QC ]"

    def __bool__(self):
        condition = (
            (self.test_instance_name and self.test_instance_id)
            or (self.test_instance_name and self.test_lab_path and self.test_set_name)
        )
        return condition
